> "If possible, the authors could create another figure to show how a substitution script is generated. I am extremely interested in what type of substitution script looks like. Is it a rule-based decision system with if-else statements?"

It is our mistake that we didn't give sufficient explanation on substitution script, and we will add a figure and extra text to fully explain it in the revised paper.
Substitution script is the code that LLMs generate to implement a mock function, sometimes it is written in if-else statements, and sometimes it is rule-based - this depends on the type of output.
This is one version of the substitution script for Iris dataset:

```csharp
using MongoDB.Bson;  

public static BsonDocument MockFunction(BsonDocument Arguments)  
{  
    double sepalLength = Arguments["sepalLength"].ToDouble();  
    double sepalWidth = Arguments["sepalWidth"].ToDouble();  
    double petalLength = Arguments["petalLength"].ToDouble();  
    double petalWidth = Arguments["petalWidth"].ToDouble();  
      
    string species = "Unknown";  
    string remarks = "";  
      
    if (petalLength < 2.0)  
    {  
        species = "Setosa";  
        remarks = "Petal length is less than 2.0, indicating Setosa.";  
    }  
    else if (petalLength >= 2.0 && petalLength < 5.0)  
    {  
        if (petalWidth < 1.5)  
        {  
            species = "Versicolor";  
            remarks = "Petal length and width are within the range for Versicolor.";  
        }  
        else  
        {  
            species = "Virginica";  
            remarks = "Petal width is greater than or equal to 1.5, indicating Virginica.";  
        }  
    }  
    else if (petalLength >= 5.0)  
    {  
        species = "Virginica";  
        remarks = "Petal length is greater than or equal to 5.0, indicating Virginica.";  
    }  
    else  
    {  
        remarks = "Unable to determine species from given dimensions.";  
    }  

    return new BsonDocument  
    {  
        { "Remarks", remarks },  
        { "Results", species },  
        { "IsReadyToCompile", true }  
    };  
}  

return MockFunction(Arguments);
```
And this is one version of the substituion script for Titanic dataset:
```csharp
using MongoDB.Bson;  

public static BsonDocument MockFunction(BsonDocument Arguments)  
{  
    // Extracting data from the Arguments BsonDocument  
    int passengerClass = Arguments["passengerClass"].AsInt32;  
    string sex = Arguments["sex"].AsString;  
    int age = Arguments["age"].AsInt32;  
    int siblingsOnBoard = Arguments["siblingsOnBoard"].AsInt32;  
    int parchOnBoard = Arguments["parchOnBoard"].AsInt32;  
    double ticketPrice = Arguments["ticketPrice"].AsDouble;  
      
    // Initialize the result fields  
    double survivalChance = 0.0;  
    string remarks = "";  

    // Simplistic logic to determine survival chance  
    // This is based on well-known historical data patterns from the Titanic  
    if (sex.ToLower() == "female")  
    {  
        survivalChance += 0.5; // Females generally had a higher survival rate  
        remarks += "Gender favorably affects survival chances. ";  
    }  

    if (passengerClass == 1)  
    {  
        survivalChance += 0.3; // First-class passengers had better survival rates  
        remarks += "First class improves survival chances. ";  
    }  

    if (age < 12)  
    {  
        survivalChance += 0.1; // Children had a higher chance of survival  
        remarks += "Being a child increases survival odds. ";  
    }  

    if (siblingsOnBoard + parchOnBoard >= 3)  
    {  
        survivalChance -= 0.1; // Large families had lower survival rates  
        remarks += "Being in a large group negatively affects survival chances. ";  
    }  

    // Make sure the survival chance is within the range [0, 1]  
    survivalChance = System.Math.Min(1.0, System.Math.Max(0.0, survivalChance));  

    return new BsonDocument  
    {  
        { "Remarks", remarks.Trim() },  
        { "Results", survivalChance },  
        { "IsReadyToCompile", true }  
    };  
}  

return MockFunction(Arguments);
```

